export function largestRectangleInHistogram(heights          )         {
const stack         =[],a=[...heights,0];let best=0;for(let i=0;i<a.length;i++){while(stack.length&&a[stack[stack.length-1]]>a[i]){const height=a[stack.pop() ],left=stack.length?stack[stack.length-1]:-1;best=Math.max(best,height*(i-left-1));}stack.push(i);}return best;
}

